// Unwrap the Supabase array. Expect exactly one case. Pull the FIRST upload
// (the combined PDF) into `upload` for downstream nodes. Throws if there is
// no case or no uploads attached yet.
//
// Also expose the current values of fields the AI may later try to autofill so
// the metadata-update node can compare and only overwrite NULL/empty values.
const arr = $input.first().json;
if (!Array.isArray(arr) || arr.length === 0) {
  throw new Error('Case not found');
}
const c = arr[0];
const uploads = Array.isArray(c.uploads) ? c.uploads : [];
if (uploads.length === 0) {
  throw new Error('Case has no uploads to break down');
}

const u = uploads[0];
const upload = {
  id:             u.id,
  filename:       u.filename,
  storage_path:   u.storage_path,
  storage_bucket: u.storage_bucket || 'Document submission',
  file_size_bytes: u.file_size_bytes || null,
  mime_type:      u.mime_type || 'application/pdf',
  page_count:     u.page_count || null,
};

return [{
  json: {
    case_id:      c.id,
    tenant_id:    c.tenant_id,
    project_id:   c.project_id,
    developer_id: c.developer_id,
    case_number:  c.case_number,
    notes:        c.notes,
    // Existing metadata snapshot — used downstream to decide whether to autofill.
    existing: {
      voucher_number_text: c.voucher_number_text || null,
      voucher_date:        c.voucher_date        || null,
      amount_sar:          (c.amount_sar === null || c.amount_sar === undefined) ? null : c.amount_sar,
      delivery_date:       c.delivery_date       || null,
      notes:               c.notes               || null,
    },
    uploads,
    upload,
    project:      c.project   || null,
    developer:    c.developer || null,
  }
}];

// Build the Anthropic /v1/messages body. ONE Claude call: classify + segment
// the Arabic disbursement PDF into typed page-range sections AND extract the
// voucher metadata (number, dates, amount, notes) so the case row can be auto-
// filled when the human created the case with blanks. We also ask Claude for
// a richer `case_metadata.extracted` block (developer/beneficiary/IBAN/invoice
// line items/etc.) which we store verbatim in dsb_cases.extracted_fields for
// human review — never auto-merged onto the typed case columns.
//
// The PDF lands in $binary.data after the Download step (responseFormat: file).
// n8n stores binaries with a base64 'data' field already — we hand that straight
// to Anthropic's document block.
const item = $input.first();
const bin = item.binary && item.binary.data;
if (!bin || !bin.data) {
  throw new Error('No binary PDF on this item');
}
const base64 = bin.data;

const system = 'You are an expert document classifier for Saudi real-estate disbursement workflows. The PDF provided is in Arabic. Identify each section by document type and page range, AND extract the headline voucher metadata, AND extract the richer document fields (developer, beneficiary, IBAN, invoice line items, etc.). Return ONLY a JSON object — no prose, no code fences. Shape:
{
  "sections": [
    {
      "kind": one of "voucher" | "invoice" | "proof_of_payment" | "completion_certificate" | "contract" | "receipt" | "other",
      "page_from": int (1-indexed),
      "page_to": int (1-indexed),
      "summary_ar": string (one short sentence in Arabic describing this section's content)
    }
  ],
  "case_metadata": {
    "voucher_number_text": string | null,
    "voucher_date":        "YYYY-MM-DD" | null,
    "amount_sar":          number | null,
    "delivery_date":       "YYYY-MM-DD" | null,
    "notes":               string | null,
    "extracted": {
      "developer_name_ar":          string | null,
      "developer_name_en":          string | null,
      "beneficiary_name_ar":        string | null,
      "beneficiary_name_en":        string | null,
      "beneficiary_account_number": string | null,
      "beneficiary_bank_name":      string | null,
      "beneficiary_iban":           string | null,
      "invoice_number":             string | null,
      "invoice_date":               "YYYY-MM-DD" | null,
      "invoice_total_sar":          number | null,
      "invoice_vat_sar":            number | null,
      "issued_to":                  string | null,
      "line_items": [
        {
          "description_ar":  string | null,
          "description_en":  string | null,
          "quantity":        number | null,
          "unit_price_sar":  number | null,
          "line_total_sar":  number | null
        }
      ] | null,
      "confidence_overall": number
    }
  }
}
Use the most specific kind possible. If a section doesn't fit any category, use "other". Page ranges must not overlap. Extract fields from the document as accurately as possible. If a field is not present, set it to null. Do not guess. Preserve Arabic strings exactly as they appear in the document. Provide English transliterations for names where helpful. For monetary values, return the number without currency symbols (e.g., 60000 not "60,000 SAR"). Dates MUST be ISO YYYY-MM-DD (convert Hijri/Arabic-numeral dates if needed). confidence_overall is a number between 0 and 1 expressing your overall confidence in the extraction.';

const claude_body = {
  model: 'claude-sonnet-4-5-20250929',
  max_tokens: 4000,
  system,
  messages: [
    {
      role: 'user',
      content: [
        { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: base64 } },
        { type: 'text', text: 'Classify and segment the document into rows AND extract case_metadata (including the richer extracted block). Return JSON only.' }
      ]
    }
  ]
};

return [{ json: { claude_body } }];

// Parse Claude's JSON. Robust extractor handles fenced code blocks and prose
// preambles. Validates each section, clamps `kind` to the allowed enum, then
// builds one dsb_breakdown_items insert row per section. Also extracts the
// optional `case_metadata` block and builds an autofill body that ONLY contains
// fields the case row currently has as NULL/empty — we never overwrite human
// input. The richer `extracted` sub-block is ALWAYS written to dsb_cases
// .extracted_fields (overwriting any prior value) because it is purely
// informational — humans review it next to the case, never auto-merged.
const item = $input.first();
const claudeResp = item.json;
const text = (claudeResp.content && claudeResp.content[0] && claudeResp.content[0].text) || '';
const tokensIn  = claudeResp.usage?.input_tokens  ?? 0;
const tokensOut = claudeResp.usage?.output_tokens ?? 0;

function extractJSON(s) {
  const stripped = s.trim().replace(/^```(json)?/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(stripped); } catch (e) {}
  const first = stripped.indexOf('{');
  const last  = stripped.lastIndexOf('}');
  if (first >= 0 && last > first) {
    try { return JSON.parse(stripped.slice(first, last + 1)); } catch (e) {}
  }
  throw new Error('Claude returned non-JSON: ' + s.slice(0, 200));
}

const parsed = extractJSON(text);
const sectionsRaw = Array.isArray(parsed.sections) ? parsed.sections : [];
const metaRaw = (parsed.case_metadata && typeof parsed.case_metadata === 'object') ? parsed.case_metadata : {};

const ALLOWED = ['voucher','invoice','proof_of_payment','completion_certificate','contract','receipt','other'];

// Pull case scope from the Unwrap node so we have tenant/case/upload IDs.
const scope = $node['Unwrap Case'].json;
const tenant_id = scope.tenant_id;
const case_id   = scope.case_id;
const upload_id = scope.upload && scope.upload.id;
if (!tenant_id || !case_id || !upload_id) {
  throw new Error('Missing scope for insert (tenant_id/case_id/upload_id)');
}

const rows = [];
let idx = 0;
for (const s of sectionsRaw) {
  if (!s || typeof s !== 'object') continue;
  const kindRaw = typeof s.kind === 'string' ? s.kind : 'other';
  const kind = ALLOWED.includes(kindRaw) ? kindRaw : 'other';
  const page_from = Number.isFinite(s.page_from) ? Math.max(1, Math.floor(s.page_from)) : null;
  const page_to   = Number.isFinite(s.page_to)   ? Math.max(1, Math.floor(s.page_to))   : null;
  if (page_from === null || page_to === null) continue;
  const summary_ar = typeof s.summary_ar === 'string' ? s.summary_ar : '';
  idx += 1;
  rows.push({
    tenant_id,
    case_id,
    upload_id,
    kind,
    page_from,
    page_to,
    summary_ar,
    source: 'ai',
    order_index: idx,
  });
}

if (rows.length === 0) {
  throw new Error('No valid sections returned by Claude');
}

// ------------------------------------------------------------------
// Build the conditional case-metadata update body.
// Rule: only include a field if (a) Claude returned a non-null value
//       AND (b) the case row currently has NULL/empty for that field.
// This prevents the AI from overwriting anything the developer typed.
// ------------------------------------------------------------------
const existing = scope.existing || {};
const metadataUpdate = {};
function isBlank(v) {
  return v === null || v === undefined || (typeof v === 'string' && v.trim() === '');
}
function validDate(s) {
  return typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);
}

if (isBlank(existing.voucher_number_text) && typeof metaRaw.voucher_number_text === 'string' && metaRaw.voucher_number_text.trim()) {
  metadataUpdate.voucher_number_text = metaRaw.voucher_number_text.trim();
}
if (isBlank(existing.voucher_date) && validDate(metaRaw.voucher_date)) {
  metadataUpdate.voucher_date = metaRaw.voucher_date;
}
if (isBlank(existing.amount_sar) && typeof metaRaw.amount_sar === 'number' && isFinite(metaRaw.amount_sar) && metaRaw.amount_sar > 0) {
  metadataUpdate.amount_sar = metaRaw.amount_sar;
}
if (isBlank(existing.delivery_date) && validDate(metaRaw.delivery_date)) {
  metadataUpdate.delivery_date = metaRaw.delivery_date;
}
if (isBlank(existing.notes) && typeof metaRaw.notes === 'string' && metaRaw.notes.trim()) {
  metadataUpdate.notes = metaRaw.notes.trim();
}

const metaUpdateKeys = Object.keys(metadataUpdate);

// ------------------------------------------------------------------
// Build the final PATCH body for dsb_cases. Conditionally-filled top-level
// fields PLUS the ALWAYS-set `extracted_fields` blob (the latest AI run).
// ------------------------------------------------------------------
const extractedRaw = (metaRaw && typeof metaRaw.extracted === 'object' && metaRaw.extracted !== null)
  ? metaRaw.extracted
  : null;
const updateBody = { ...metadataUpdate, extracted_fields: extractedRaw };

return [{
  json: {
    rows,
    section_count: rows.length,
    tokens_in:  tokensIn,
    tokens_out: tokensOut,
    case_id,
    tenant_id,
    case_metadata_raw: metaRaw,
    case_metadata_update: metadataUpdate,
    case_metadata_update_keys: metaUpdateKeys,
    case_metadata_will_update: metaUpdateKeys.length > 0,
    extracted_fields: extractedRaw,
    update_body: updateBody,
  }
}];
